#!/usr/bin/env node
// Build the megastructure catalogue (H5324): every data/megastructure/<dict>.json
// that passes the schema and the semantic checks, bundled with per-dictionary
// counts into src/data/megastructure/megastructure_catalogue.json plus its
// .source.json envelope. A dictionary is added by committing its <dict>.json;
// nothing here names the pilot dictionaries.
//
// The per-dictionary JSON is hand-curated (generated by the fill scripts in
// scripts/megastructure/), so this builder needs no sibling checkout and runs in CI.

import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { licenseFields, generatedAtForPayload, readJsonIfExists } from "./lib/dataset-meta.mjs";
import { checkSchema, parseInventory, semanticChecks, summarize } from "./lib/megastructure.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const DATA_DIR = path.join(ROOT, "data", "megastructure");
export const SCHEMA_PATH = path.join(ROOT, "data", "schema", "megastructure-component.schema.json");
export const INVENTORY_PATH = path.join(DATA_DIR, "scan_inventory.tsv");
const OUT_DIR = path.join(ROOT, "src", "data", "megastructure");
export const JSON_OUT = path.join(OUT_DIR, "megastructure_catalogue.json");
const SOURCE_OUT = path.join(OUT_DIR, "megastructure_catalogue.source.json");
const GENERATED_BY = "scripts/build-megastructure.mjs";
const SCHEMA_VERSION = "1.0.0";

// Sibling commits the pilot evidence was measured against (recorded, not re-read at build time).
export const SOURCE_PINS = [
  { repo: "sanskrit-lexicon/csl-orig", commit: "f4c08c5", used: "mw.txt supplement markers; skd.txt body extent" },
  { repo: "sanskrit-lexicon/csl-pywork", commit: "4943a6d", used: "mwauth/tooltip.txt, mwab/mwab_input.txt" },
  { repo: "sanskrit-lexicon/csl-websanlexicon", commit: "7a69600", used: "distinctfiles/{mw,skd}/web/webtc/pdffiles.txt scan maps" },
  { repo: "sanskrit-lexicon/MWS", commit: "8261e06", used: "prefaces/mwpref01-29.md OCR" }
];

export function catalogueFiles(dir = DATA_DIR) {
  return fs.readdirSync(dir).filter((name) => /^[a-z][a-z0-9]*\.json$/.test(name)).sort();
}

/** Load, check and summarise every catalogue; returns { catalogues, errors, coverage }. */
export function loadAndCheck({ dir = DATA_DIR, schemaPath = SCHEMA_PATH, inventoryPath = INVENTORY_PATH } = {}) {
  const schema = JSON.parse(fs.readFileSync(schemaPath, "utf8"));
  const inventory = parseInventory(fs.readFileSync(inventoryPath, "utf8"));
  const fileExists = (rel) => fs.existsSync(path.join(ROOT, rel));
  const catalogues = [];
  const errors = [];
  const coverage = [];
  for (const name of catalogueFiles(dir)) {
    const catalogue = JSON.parse(fs.readFileSync(path.join(dir, name), "utf8"));
    const label = name.replace(/\.json$/, "");
    if (catalogue.dict !== label) errors.push(`${name}: dict "${catalogue.dict}" does not match the file name`);
    errors.push(...checkSchema(schema, catalogue).map((message) => `${name} ${message}`));
    const semantic = semanticChecks(catalogue, inventory, fileExists);
    errors.push(...semantic.errors.map((message) => `${name} ${message}`));
    coverage.push(...semantic.coverage.map((row) => ({ dict: catalogue.dict, ...row })));
    catalogues.push(catalogue);
  }
  const inventoryDicts = new Set(inventory.map((row) => row.dict));
  for (const dict of inventoryDicts) {
    if (!catalogues.some((catalogue) => catalogue.dict === dict)) errors.push(`scan_inventory.tsv lists ${dict}, but data/megastructure/${dict}.json is missing`);
  }
  return { catalogues, errors, coverage };
}

export function buildPayload(catalogues, coverage, { generatedAt } = {}) {
  const payload = {
    schemaVersion: SCHEMA_VERSION,
    ...licenseFields(),
    generatedAt: generatedAt ?? null,
    generatedBy: GENERATED_BY,
    componentSchema: "data/schema/megastructure-component.schema.json",
    dicts: catalogues.map((catalogue) => catalogue.dict),
    summary: catalogues.map(summarize),
    coverage,
    catalogues
  };
  if (!generatedAt) payload.generatedAt = generatedAtForPayload(readJsonIfExists(JSON_OUT, fs), payload);
  return payload;
}

function main() {
  const { catalogues, errors, coverage } = loadAndCheck();
  if (errors.length) {
    console.error(`Megastructure catalogue refused (${errors.length} errors):\n${errors.map((e) => `- ${e}`).join("\n")}`);
    process.exit(1);
  }
  const payload = buildPayload(catalogues, coverage);
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(JSON_OUT, `${JSON.stringify(payload, null, 2)}\n`);
  let commit = "unknown";
  try {
    commit = execSync("git rev-parse HEAD", { cwd: ROOT, encoding: "utf8" }).trim();
  } catch {}
  const envelope = {
    dataset: "megastructure_catalogue",
    commit,
    generatedAt: payload.generatedAt,
    generatedBy: GENERATED_BY,
    ...licenseFields(),
    inputs: ["data/schema/megastructure-component.schema.json", "data/megastructure/scan_inventory.tsv", ...catalogueFiles().map((name) => `data/megastructure/${name}`)],
    sourcePins: SOURCE_PINS,
    schemaVersion: SCHEMA_VERSION
  };
  fs.writeFileSync(SOURCE_OUT, `${JSON.stringify(envelope, null, 2)}\n`);
  for (const row of payload.summary) console.log(`${row.dict}: ${row.components} components (${row.topLevel} top-level, ${row.decoding} decode body notation)`);
  console.log(`- ${path.relative(process.cwd(), JSON_OUT)}\n- ${path.relative(process.cwd(), SOURCE_OUT)}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
